fn choose(indices: Vec<u8>, choices: Vec<Vec<f64>>) -> Vec<f64> {
    // The length of the result is the same as the length of the indices.
    let mut result = Vec::with_capacity(indices.len());

    for (col, &idx) in indices.iter().enumerate() {
        // Cast u8 index to usize to index into the choices matrix.
        let row_idx = idx as usize;
        // It's guaranteed that every row has length == indices.len(),
        // and idx is a valid row index.
        result.push(choices[row_idx][col]);
    }

    result
}

